<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ChevronDown, ClipboardList } from 'lucide-vue-next'
import { ElButton } from 'element-plus'
import ListStatusTabs from '@/components/commerce/ListStatusTabs.vue'
import DemoImage from '@/components/commerce/DemoImage.vue'
import { useProductsStore, type ApprovalRecord } from '@/stores/products'
import { useCommerceStore } from '@/stores/commerce'

const route = useRoute(), router = useRouter(), products = useProductsStore(), commerce = useCommerceStore()
const product = computed(() => products.products.find(p => p.id === route.params.id))
const filter = ref('all'), selected = ref<number | null>(null), example = ref(false)
const tabs = [['all','全部'], ['待审','待审'], ['通过','通过'], ['驳回','驳回']]
const examples: ApprovalRecord[] = [
  {time:'2026/10/20 16:29:45',type:'上架审批',status:'通过',note:'',parkName:'上海临港新片区智能制造产业园',approver:'园区运营',reviewedAt:'2026/10/21 16:29:45',events:[{time:'2026/10/20 16:29:45',action:'提交上架审批',actor:'供应商',status:'已提交'},{time:'2026/10/21 16:29:45',action:'审核通过并上架',actor:'园区运营',status:'通过'}]},
  {time:'2026/10/24 16:29:45',type:'上架审批',status:'通过',note:'',parkName:'成都高新区智慧园区',approver:'园区运营',reviewedAt:'2026/10/25 16:29:45',events:[{time:'2026/10/22 16:29:45',action:'提交上架审批',actor:'供应商',status:'已提交'},{time:'2026/10/23 16:29:45',action:'审核驳回',actor:'园区运营',status:'驳回',opinion:'资质材料不完整，请补充检测报告后重提'},{time:'2026/10/24 16:29:45',action:'再次提交上架审批',actor:'供应商',status:'已提交'},{time:'2026/10/25 16:29:45',action:'审核通过并上架',actor:'园区运营',status:'通过'}]},
  {time:'2026/10/29 16:29:45',type:'上架审批',status:'待审',note:'',parkName:'天府新区产业园',events:[{time:'2026/10/29 16:29:45',action:'提交上架审批',actor:'供应商',status:'已提交'}]},
]
const records = computed(() => (example.value ? examples : product.value?.approvalLog || []).map((record, index) => ({ record, index })).reverse())
const count = (status:string) => records.value.filter(({record}) => status === 'all' || record.status === status).length
const filtered = computed(() => records.value.filter(({record}) => filter.value === 'all' || record.status === filter.value))
watch(filtered, rows => { selected.value = rows[0]?.index ?? null }, { immediate:true })
const parkName = (row:ApprovalRecord) => row.parkName || (row.parkId && commerce.joinedParks.find(park => park.id === row.parkId)?.name) || '—'
const stateClass = (state:string) => state === '通过' ? 'approved' : state === '驳回' ? 'rejected' : state === '待审' ? 'pending' : 'neutral'
const typeName = (type:string) => ({'商品上架':'上架审批','上架':'上架审批','调价':'调价审批'} as Record<string,string>)[type] || type
function timeline(row:ApprovalRecord) { return row.events?.length ? row.events : [{time:row.time,action:row.type, status:row.status, ...(row.opinion ? {opinion:row.opinion} : {})}] }
function back() { const target = typeof route.query.returnTo === 'string' ? route.query.returnTo : ''; if (target.startsWith(`/product/detail/${encodeURIComponent(String(route.params.id))}`) || target.startsWith(`/product/detail/${String(route.params.id)}`)) router.push(target); else router.push({path:'/product',query:{restoreList:'1'}}) }
function toggleExample() {example.value = !example.value; filter.value = 'all'}
</script>

<template>
  <div class="biz-page approval-page">
    <header class="approval-header">
      <button class="back-link" @click="back"><ArrowLeft :size="16"/>{{route.query.returnTo ? '返回商品详情' : '返回商品管理'}}</button>
      <div class="header-title"><span class="header-icon"><ClipboardList :size="20"/></span><div><h1>审批记录</h1><p v-if="product">{{product.name}} <span>·</span> 商品编码 {{product.code || '—'}}</p></div></div>
      <ElButton v-if="product" @click="toggleExample">{{example ? '返回实际记录' : '查看示例'}}</ElButton>
    </header>
    <section v-if="!product" class="biz-empty"><h3>未找到该商品</h3><p>商品可能已删除或不属于当前供应商。</p><ElButton @click="back">返回商品管理</ElButton></section>
    <template v-else>
      <div v-if="example" class="example-notice">当前为审批过程示例，仅供查看，不会写入商品记录。<button @click="toggleExample">返回实际记录</button></div>
      <section class="approval-workspace">
        <div class="list-intro"><div><h2>审批记录</h2><p>按园区查看审批结果和完整过程</p></div><span>共 {{records.length}} 条记录</span></div>
        <ListStatusTabs :model-value="filter" :items="tabs" :count="count" @update:model-value="filter=$event" />
        <div v-if="!filtered.length" class="empty-records"><div class="empty-icon"><ClipboardList :size="22"/></div><h3>{{records.length ? '该状态下暂无审批记录' : '暂无审批记录'}}</h3><p>{{records.length ? '可以切换其他状态查看。' : '提交上架、调价或资料变更审核后，记录会显示在这里。'}}</p><ElButton v-if="!records.length && !example" @click="toggleExample">查看审批过程示例</ElButton><ElButton v-else-if="filter!=='all'" @click="filter='all'">查看全部记录</ElButton></div>
        <div v-else class="approval-table-wrap"><table class="approval-table"><colgroup><col class="time-col"/><col class="type-col"/><col class="park-col"/><col class="status-col"/><col class="opinion-col"/><col class="actor-col"/><col class="time-col"/><col class="expand-col"/></colgroup>
          <thead><tr><th>提交时间</th><th>审批类型</th><th>园区</th><th>状态</th><th>审批意见</th><th>审批人</th><th>审批时间</th><th><span class="sr-only">审批过程</span></th></tr></thead>
          <tbody v-for="{record,index} in filtered" :key="index">
            <tr class="record-row" :class="{selected:selected===index}" @click="selected=selected===index?null:index">
              <td class="time-text">{{record.time || '—'}}</td><td>{{typeName(record.type)}}</td><td class="park-cell">{{parkName(record)}}</td><td><span class="state-pill" :class="stateClass(record.status)">{{record.status}}</span></td><td class="opinion-cell" :title="record.opinion || ''">{{record.opinion || '—'}}</td><td>{{record.approver || '—'}}</td><td class="time-text">{{record.reviewedAt || '—'}}</td><td><button class="expand-action" :aria-expanded="selected===index" @click.stop="selected=selected===index?null:index">{{selected===index?'收起':'展开'}}<ChevronDown :size="14" :class="{rotated:selected===index}"/></button></td>
            </tr>
            <tr v-if="selected===index" class="timeline-row"><td colspan="8"><div class="timeline-panel"><div class="timeline-context"><div class="product-thumb"><DemoImage :source="product.cover" empty-text="暂无图片"/></div><div><strong>{{product.name}}</strong><p>{{parkName(record)}} <span>·</span> {{typeName(record.type)}} <span>·</span> {{record.status}}</p></div></div><div class="timeline-content"><h3>审批过程</h3><ol><li v-for="(event,eventIndex) in timeline(record)" :key="eventIndex" :class="stateClass(event.status || '')"><span class="event-dot"></span><div class="event-body"><div class="event-title"><strong>{{event.action}}</strong><span v-if="event.status" class="event-status" :class="stateClass(event.status)">{{event.status}}</span></div><p>{{event.actor || '—'}} <span>·</span> {{event.time || '—'}}</p><div v-if="event.opinion" class="event-opinion" :class="{rejected:event.status==='驳回'}">{{event.status==='驳回'?'驳回意见':'说明'}}：{{event.opinion}}</div></div></li></ol><p v-if="!record.events?.length" class="legacy-note">该记录未保存完整审批过程，以上为已记录的信息。</p></div></div></td></tr>
          </tbody>
        </table></div>
      </section>
    </template>
  </div>
</template>
<style scoped>
.approval-page{max-width:var(--biz-content-width);min-width:0}.approval-header{display:flex;align-items:center;gap:18px;margin-bottom:26px}.back-link{display:flex;align-items:center;gap:6px;flex:none;border:0;background:none;padding:8px 0;color:#577098;font:inherit;font-size:13px;cursor:pointer}.back-link:hover,.expand-action:hover{color:#244cc0}.header-title{display:flex;align-items:center;gap:12px;flex:1;min-width:0;padding-left:18px;border-left:1px solid #e4eaf2}.header-icon{display:grid;place-items:center;width:42px;height:42px;flex:none;border-radius:10px;background:#edf2ff;color:#355bc6}.header-title h1{font-size:21px;margin:0 0 4px;color:#20314d}.header-title p{margin:0;color:#71829a;font-size:12px;overflow-wrap:anywhere}.header-title p span,.timeline-context p span,.event-body p span{margin:0 5px;color:#a4b0c2}.example-notice{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:11px 14px;margin-bottom:14px;border:1px solid #e6eaf1;border-radius:7px;background:#f8f9fc;color:#64748b;font-size:12px}.example-notice button{border:0;background:none;color:#315bc8;cursor:pointer;white-space:nowrap}.approval-workspace{border:1px solid #e2e8f1;border-radius:9px;background:#fff;overflow:hidden}.list-intro{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:20px 22px 0}.list-intro h2{font-size:15px;margin:0;color:#243855}.list-intro p{font-size:12px;color:#8492a5;margin:6px 0 0}.list-intro>span{font-size:12px;color:#8795a8}.approval-workspace :deep(.list-status-bar){margin:12px 22px 0}.approval-workspace :deep(.list-status-tabs button){padding:11px 12px}.approval-table-wrap{overflow-x:auto;border-top:1px solid #e7ecf4}.approval-table{border-collapse:collapse;table-layout:fixed;width:100%;min-width:960px;text-align:left;font-size:12px}.approval-table .time-col{width:15%}.approval-table .type-col{width:9%}.approval-table .park-col{width:16%}.approval-table .status-col{width:7%}.approval-table .opinion-col{width:12%}.approval-table .actor-col{width:9%}.approval-table .expand-col{width:7%}.approval-table th{background:#f7f9fc;color:#708199;font-weight:500;padding:13px 10px}.approval-table td{padding:15px 10px;border-top:1px solid #edf1f6;vertical-align:middle;color:#334660;line-height:1.55}.approval-table th:first-child,.approval-table td:first-child{padding-left:22px}.record-row{cursor:pointer}.record-row:hover,.record-row.selected{background:#fafcff}.record-row .time-text{color:#61748f;white-space:nowrap;font-variant-numeric:tabular-nums}.park-cell{overflow-wrap:anywhere}.opinion-cell{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:0;color:#677b95!important}.state-pill,.event-status{display:inline-flex;align-items:center;white-space:nowrap;border-radius:20px;padding:3px 9px;font-size:12px;line-height:1.4;font-weight:600}.state-pill.pending,.event-status.pending{color:#a46710;background:#fff7e7}.state-pill.approved,.event-status.approved{color:#167c5f;background:#eaf8f1}.state-pill.rejected,.event-status.rejected{color:#b74239;background:#fff0ef}.state-pill.neutral,.event-status.neutral{color:#667790;background:#f0f3f7}.expand-action{display:inline-flex;align-items:center;gap:3px;border:0;background:none;color:#315bc8;font:inherit;white-space:nowrap;cursor:pointer;padding:4px}.expand-action svg{transition:transform .15s}.expand-action svg.rotated{transform:rotate(180deg)}.timeline-row td{padding:0 22px 18px!important;border-top:0;background:#fafcff}.timeline-panel{display:grid;grid-template-columns:minmax(180px,25%) minmax(0,1fr);gap:24px;border:1px solid #e6ecf5;border-radius:7px;background:#fff;padding:18px 20px}.timeline-context{display:flex;gap:11px;align-items:flex-start;border-right:1px solid #edf1f6;padding-right:18px}.product-thumb{width:44px;height:44px;flex:none;border-radius:6px;overflow:hidden;background:#f2f5fa}.timeline-context strong{font-size:13px;color:#253954}.timeline-context p{margin:6px 0 0;color:#7b8da5;line-height:1.6;overflow-wrap:anywhere}.timeline-content h3{font-size:13px;margin:0 0 16px;color:#283d59}.timeline-content ol{list-style:none;padding:0;margin:0}.timeline-content li{position:relative;padding:0 0 18px 22px;border-left:1px solid #dfe6f0;margin-left:5px}.timeline-content li:last-child{border-left-color:transparent;padding-bottom:0}.event-dot{position:absolute;left:-5px;top:4px;width:9px;height:9px;border-radius:50%;background:#4672d3;box-shadow:0 0 0 3px #fff}.timeline-content li.approved .event-dot{background:#1c9f72}.timeline-content li.rejected .event-dot{background:#d84d46}.timeline-content li.pending .event-dot{background:#e4a23d}.event-title{display:flex;align-items:center;justify-content:space-between;gap:12px}.event-title strong{font-size:13px;color:#2d405a}.event-status{font-size:11px;padding:2px 7px}.event-body p{margin:5px 0 0;color:#8291a6}.event-opinion{margin-top:9px;padding:9px 11px;border-radius:5px;background:#f5f7fb;color:#5d708c;line-height:1.6;overflow-wrap:anywhere}.event-opinion.rejected{background:#fff4f3;color:#b74239}.legacy-note{font-size:12px;color:#8a98a9;margin:14px 0 0}.empty-records{text-align:center;padding:58px 20px;color:#8291a5;border-top:1px solid #e7ecf4}.empty-icon{display:grid;place-items:center;margin:0 auto 12px;width:46px;height:46px;background:#f2f5fa;color:#91a0b5;border-radius:50%}.empty-records h3{font-size:14px;color:#435975;margin:0 0 7px}.empty-records p{font-size:12px;margin:0 0 18px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:850px){.timeline-panel{grid-template-columns:1fr}.timeline-context{border-right:0;border-bottom:1px solid #edf1f6;padding:0 0 14px}.approval-header{flex-wrap:wrap}.header-title{min-width:220px}}
</style>
